 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The background is the most frequent color; connect successive markers
    # in each row and column with the line color used by this task.
    from collections import Counter
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    marker_colors = {value for row in grid for value in row if value != background}
    for r in range(h):
        marks = [c for c, value in enumerate(grid[r]) if value in marker_colors]
        for left, right in zip(marks, marks[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] in marker_colors]
        for top, bottom in zip(marks, marks[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
